'use client';
import { useState } from 'react';
import { Pencil, Plus, Trash2, X } from 'lucide-react';
import { API, Product } from '@/lib/api';
const blank = { name: '', slug: '', price: 0, category: 'oversized', inventory: 0, published: true, colorName: 'Jet Black', colorHex: '#0b0b0b', images: '', tags: 'new', fabric: 'Heavyweight cotton', details: 'Premium quality' };
export default function ProductManager({ initial }: { initial: Product[] }) { const [items, setItems] = useState<any[]>(initial); const [editing, setEditing] = useState<any | null>(null); const save = async (e: React.FormEvent<HTMLFormElement>) => { e.preventDefault(); const raw = Object.fromEntries(new FormData(e.currentTarget)); const body = { ...raw, price: Number(raw.price), inventory: Number(raw.inventory), published: raw.published === 'on', images: String(raw.images).split(',').map(x => x.trim()).filter(Boolean), tags: String(raw.tags).split(',').map(x => x.trim()).filter(Boolean), details: String(raw.details).split('\n').filter(Boolean) }; const r = await fetch(`${API}/products${editing.id ? `/${editing.id}` : ''}`, { method: editing.id ? 'PATCH' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); if (r.ok) { const saved = await r.json(); setItems(current => editing.id ? current.map(x => x.id === saved.id ? saved : x) : [saved, ...current]); setEditing(null); } }; const remove = async (id: string) => { if (!confirm('Delete this product?')) return; const r = await fetch(`${API}/products/${id}`, { method: 'DELETE' }); if (r.ok) setItems(current => current.filter(x => x.id !== id)); }; return <><div className="mb-5 flex items-center justify-between"><p className="text-sm font-bold">{items.length} products</p><button onClick={() => setEditing(blank)} className="rounded-full bg-ink px-5 py-3 text-xs font-bold text-white"><Plus size={15} className="mr-2 inline" /> Add product</button></div><div className="card overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead><tr className="bg-[#fafaf8] text-[10px] font-bold tracking-[.16em] text-muted uppercase"><th className="px-5 py-4">Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody>{items.map(p => <tr className="border-t border-line" key={p.id}><td className="px-5 py-4"><p className="font-bold">{p.name}</p><p className="text-xs text-muted">{p.slug}</p></td><td>{p.category}</td><td>৳{p.price.toLocaleString()}</td><td>{p.inventory}</td><td>{p.published ? 'Published' : 'Draft'}</td><td><button onClick={() => setEditing({ ...p, images: p.images.join(', '), tags: p.tags?.join(', '), details: p.details?.join('\n') })} className="mr-2 rounded border border-line p-2"><Pencil size={14} /></button><button onClick={() => remove(p.id)} className="rounded border border-red-200 p-2 text-red-600"><Trash2 size={14} /></button></td></tr>)}</tbody></table></div>{editing && <div className="fixed inset-0 z-50 grid place-items-center bg-black/40 p-4"><form onSubmit={save} className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-7"><div className="mb-6 flex justify-between"><h2 className="text-xl font-black">{editing.id ? 'Edit product' : 'New product'}</h2><button type="button" onClick={() => setEditing(null)}><X /></button></div><div className="grid gap-4 sm:grid-cols-2">{[['name','Name'],['slug','Slug'],['price','Price'],['inventory','Inventory'],['category','Category'],['colorName','Color name'],['colorHex','Color hex'],['fabric','Fabric']].map(([name,label]) => <Field key={name} name={name} label={label} value={editing[name]} />)}<label className="sm:col-span-2"><Label>Image paths (comma separated)</Label><input name="images" defaultValue={editing.images} className="input" /></label><label className="sm:col-span-2"><Label>Tags (comma separated)</Label><input name="tags" defaultValue={editing.tags} className="input" /></label><label className="sm:col-span-2"><Label>Details (one per line)</Label><textarea name="details" defaultValue={editing.details} rows={4} className="input h-auto py-3" /></label><label className="flex items-center gap-2"><input name="published" type="checkbox" defaultChecked={editing.published} /> Published</label></div><button className="mt-6 w-full rounded-lg bg-ink py-4 text-xs font-bold text-white uppercase">Save product</button></form></div>}</>; }
function Label({ children }: { children: React.ReactNode }) { return <span className="mb-2 block text-[10px] font-bold tracking-[.15em] text-muted uppercase">{children}</span>; }
function Field({ name, label, value }: any) { return <label><Label>{label}</Label><input required name={name} defaultValue={value} type={name === 'price' || name === 'inventory' ? 'number' : 'text'} className="input" /></label>; }
